import random
def findKthLargest(nums, k):
    def quickselect(low, high, target_idx):
        if low == high:
            return nums[low]
        pivot_idx = random.randint(low, high)
        nums[pivot_idx], nums[high] = nums[high], nums[pivot_idx]
        pivot = nums[high]
        i = low
        for j in range(low, high):
            if nums[j] < pivot:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1
        nums[i], nums[high] = nums[high], nums[i]
        if i == target_idx:
            return nums[i]
        elif i < target_idx:
            return quickselect(i + 1, high, target_idx)
        else:
            return quickselect(low, i - 1, target_idx)
    return quickselect(0, len(nums) - 1, len(nums) - k)
